<?= $this->section('scripts') ?><script>
$(function () {
  const $rows = $('#audit-table tbody tr'); let currentPage = 1;
  const label = (key) => String(key || '').replace(/_/g, ' ').replace(/\b\w/g, (c) => c.toUpperCase());
  const value = (item) => String(item === null || item === undefined || item === '' ? 'Not recorded' : item);
  function normaliseDate(raw) { const value = String(raw || '').trim(); if (/^\d{2}-\d{2}-\d{4}$/.test(value)) { const parts = value.split('-'); return parts[2] + '-' + parts[1] + '-' + parts[0]; } return value; }
  function filterRows() { const search = String($('#audit-search').val() || '').toLowerCase(), from = normaliseDate($('#audit-date').val()), to = normaliseDate($('#audit-date-to').val()), action = String($('#audit-action').val() || '').toLowerCase(), entity = String($('#audit-entity').val() || '').toLowerCase(), user = String($('#audit-user').val() || '').toLowerCase(), sort = String($('#audit-sort').val() || 'newest'), pageSize = parseInt($('#audit-page-size').val(), 10) || 100; const matched = $rows.toArray().filter((row) => { const $row = $(row), text = $row.text().toLowerCase(), time = String($row.find('td').eq(0).attr('data-order') || ''), rawAction = String($row.attr('data-raw-action') || ''), entityText = String($row.attr('data-entity') || ''), actorText = $row.find('td').eq(2).text().toLowerCase(); return (!search || text.indexOf(search) >= 0) && (!from || time.slice(0, 10) >= from) && (!to || time.slice(0, 10) <= to) && (!action || rawAction.indexOf(action) >= 0) && (!entity || entityText.indexOf(entity) >= 0) && (!user || actorText.indexOf(user) >= 0); }); matched.sort((a, b) => { const av = sort === 'action' ? $(a).attr('data-action-display') || '' : sort === 'actor' ? $(a).find('td').eq(2).text() : sort === 'entity' ? $(a).find('td').eq(1).text() : $(a).find('td').eq(0).attr('data-order') || ''; const bv = sort === 'action' ? $(b).attr('data-action-display') || '' : sort === 'actor' ? $(b).find('td').eq(2).text() : sort === 'entity' ? $(b).find('td').eq(1).text() : $(b).find('td').eq(0).attr('data-order') || ''; const comparison = String(av).localeCompare(String(bv), undefined, { numeric: true, sensitivity: 'base' }); return sort === 'newest' ? -comparison : comparison; }); $('#audit-table tbody').append(matched); $rows.hide(); const pages = Math.max(1, Math.ceil(matched.length / pageSize)); currentPage = Math.min(currentPage, pages); matched.slice((currentPage - 1) * pageSize, currentPage * pageSize).forEach((row) => $(row).show()); $('#audit-result-count').text(matched.length + ' matching event' + (matched.length === 1 ? '' : 's')); $('#audit-page-label').text('Page ' + currentPage + ' of ' + pages); $('#audit-page-prev').prop('disabled', currentPage <= 1); $('#audit-page-next').prop('disabled', currentPage >= pages); }
  $('#audit-search,#audit-date,#audit-date-to,#audit-action,#audit-entity,#audit-user').on('input change', function () { currentPage = 1; filterRows(); }); $('#audit-sort').on('change', function () { currentPage = 1; filterRows(); }); $('#audit-page-size').on('change', function () { currentPage = 1; filterRows(); });
  $('#audit-page-prev').on('click', function () { if (currentPage > 1) { currentPage -= 1; filterRows(); } }); $('#audit-page-next').on('click', function () { currentPage += 1; filterRows(); });
  $('#audit-reset').on('click', function () { $('#audit-search,#audit-date,#audit-date-to,#audit-action,#audit-entity,#audit-user').val(''); $('#audit-sort').val('newest'); $('#audit-page-size').val('100'); currentPage = 1; filterRows(); });
  function renderList($target, items) { $target.empty(); if (!items || !items.length) { $target.append($('<div class="audit-detail-empty">No additional information recorded.</div>')); return; } items.forEach((item) => { const $dt = $('<dt>').text(item.label || label(item.key)); const $dd = $('<dd>').text(value(item.value)); $target.append($dt, $dd); }); }
  $(document).on('click', '.audit-detail', function () { let detail = {}; try { detail = JSON.parse($(this).attr('data-detail') || '{}'); } catch (e) {} $('#audit-detail-action').text(value(detail.action)); $('#audit-detail-actor').text(value(detail.actor)); $('#audit-detail-actor-email').text(detail.actor_email ? 'Email: ' + detail.actor_email : ''); $('#audit-detail-entity-type').text(value(detail.entity_type)); $('#audit-detail-entity').text(value(detail.entity_name || detail.entity)); $('#audit-detail-time').text(value(detail.time)); renderList($('#audit-detail-fields'), detail.fields); renderList($('#audit-detail-technical'), Object.entries(detail.technical || {}).map(([key, item]) => ({ label: label(key), value: item }))); const $changes = $('#audit-detail-changes').empty(); if (!detail.changes || !detail.changes.length) { $changes.append($('<tr>').append($('<td colspan="3" class="text-muted">No field-level changes recorded.</td>'))); } else { detail.changes.forEach((item) => $changes.append($('<tr>').append($('<th scope="row">').text(value(item.field)), $('<td>').text(value(item.old)), $('<td>').text(value(item.new))))); } });
  filterRows();
});
</script><?= $this->endSection() ?>
